INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('62b03494-8eed-53bb-965c-6f2932f8d835', 'faadc2c2-dab8-5b07-8f5e-cc46217b83ac', 'service_type', 'Service Type', 'Captures the business meaning of service type for the TelecomService. It is interpreted together with the entity''s other attributes and relationships to support the processes that manage this record. Used when creating, reviewing, searching, validating, reporting on, or integrating TelecomService records, where applicable. Its meaning is specific to TelecomService; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Represents the mobile state or classification in the context of TelecomService. Represents the fixed state or classification in the context of TelecomService. Represents the broadband state or classification in the context of TelecomService. Represents the voice state or classification in the context of TelecomService. Represents the data state or classification in the context of TelecomService. Represents the iot state or classification in the context of TelecomService. Represents the other state or classification in the context of TelecomService. Required because the business model cannot reliably interpret the record for its declared purpose without this value.', 1021, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a76694da-8ec4-57a0-94ec-ab49bc7aa6cf', 'faadc2c2-dab8-5b07-8f5e-cc46217b83ac', 'status', 'Status', 'The lifecycle state of the record. It controls which business actions are normally permitted and how the record is treated by related processes. Used when creating, reviewing, searching, validating, reporting on, or integrating TelecomService records, where applicable. Its meaning is specific to TelecomService; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Represents the pending state or classification in the context of TelecomService. Represents the active state or classification in the context of TelecomService. Represents the suspended state or classification in the context of TelecomService. Represents the terminated state or classification in the context of TelecomService. Required because the business model cannot reliably interpret the record for its declared purpose without this value.', 1022, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cdcc6bb7-0985-529d-aba0-9a466cd5dc5f', 'faadc2c2-dab8-5b07-8f5e-cc46217b83ac', 'activation_date', 'Activation Date', 'Records the business date associated with the activation. It is used in chronology, eligibility, scheduling, reporting, and related business rules. Used when creating, reviewing, searching, validating, reporting on, or integrating TelecomService records, where applicable. Its meaning is specific to TelecomService; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Optional because the business concept can remain valid when this value is not yet known or is not applicable.', 15, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
