VALUES ('be251be2-f0b3-5898-9e78-2febb15e4116', 'faadc2c2-dab8-5b07-8f5e-cc46217b83ac', 'termination_date', 'Termination Date', 'Records the business date associated with the termination. It is used in chronology, eligibility, scheduling, reporting, and related business rules. Used when creating, reviewing, searching, validating, reporting on, or integrating TelecomService records, where applicable. Its meaning is specific to TelecomService; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Optional because the business concept can remain valid when this value is not yet known or is not applicable.', 15, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
