VALUES ('63f5db39-5784-56c8-b659-624aba60705c', 'faadc2c2-dab8-5b07-8f5e-cc46217b83ac', 'customer_id', 'Customer', 'Connects TelecomService to Customer so related business context can be navigated and enforced. Used when processes need to find or reason about Customer records associated with a TelecomService. The declared cardinality 1 expresses how many related records may participate in the relationship. The relationship is part of the CEDM semantic graph and is interpreted together with source and target entities, ownership, conditions, and invariants.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
