INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2e783b3c-4705-594c-a677-3911d8bf122d', 'Telecom Subscription', 'Maintain Telecom Subscription records', 'Create, find and maintain Telecom Subscription records. The list shows every Telecom Subscription you have access to — select a row to open it, or use New to add one. Each row is a single Telecom Subscription, described by 7 fields.

Id and Subscription Number are unique: no two Telecom Subscription records may share the same value, and a save that would duplicate one is rejected. Subscription Number, Status, Start Date, Customer and Service must be filled in before the record can be saved.

Every Telecom Subscription points at Customer. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Telecom Subscription then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Telecom Subscription with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('04632e3d-a202-57ce-b8cd-99c72a42252c', 'bus_telecom_subscription', 'Telecom Subscription', 'Represents a telecommunications entity called TelecomSubscription within the CEDM business model. TelecomSubscription is a business concept with its own identity and lifecycle. It captures information that must remain understandable independently of a database, API, or user interface. Used by business processes, transactions, forms, reports, integrations, and domain capabilities that create, find, change, or relate TelecomSubscription records. The entity participates in a wider business graph through relationships with Customer, TelecomService, Product, Vehicle. These relationships provide the context needed to interpret the record rather than treating its fields as isolated database columns. The entity lifecycle is governed by its status, invariants, and related business processes. State changes must preserve the declared business meaning and relationships. A typical TelecomSubscription record represents one identifiable business occurrence or master-data object that can be referenced by related CEDM processes.', 'A', FALSE, FALSE, FALSE, TRUE, '2e783b3c-4705-594c-a677-3911d8bf122d', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
