VALUES ('8c82efd4-8578-5019-a689-1904f5c20269', '2e783b3c-4705-594c-a677-3911d8bf122d', '04632e3d-a202-57ce-b8cd-99c72a42252c', 'Telecom Subscription', 'Shows one Telecom Subscription at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 5 fields marked with a red asterisk (*) must have a value before Save will accept the record. Customer is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
