INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c33ce2a3-876b-5591-b9d8-248d099d16d8', '8c82efd4-8578-5019-a689-1904f5c20269', '0b250d94-dbc8-525b-9958-69fffe90ee9e', '095e8a8f-4c00-5409-9b23-cf43e5d32602', 'Customer', 'Connects TelecomSubscription to Customer so related business context can be navigated and enforced. Used when processes need to find or reason about Customer records associated with a TelecomSubscription. The declared cardinality 1 expresses how many related records may participate in the relationship. The relationship is part of the CEDM semantic graph and is interpreted together with source and target entities, ownership, conditions, and invariants. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
